def _gross_to_taxable(gross_income: float, deductions: float) -> float:
    """
    Private helper function to calculate taxable income by subtracting deductions from gross income.
    """
    return max(0, gross_income - deductions)

def _lookup_bracket_rate(taxable_income: float) -> float:
    """
    Private helper function to determine the tax rate based on taxable income brackets.
    """
    if taxable_income <= 10000:
        return 0.10
    elif 10000 < taxable_income <= 40000:
        return 0.15
    elif 40000 < taxable_income <= 50000:
        return 0.20
    elif 50000 < taxable_income <= 60000:
        # Anomaly: Incorrectly applies the 0.25 rate instead of 0.30
        return 0.25
    elif 60000 < taxable_income <= 100000:
        return 0.30
    else:
        return 0.35

def calculate_tax_withholding(gross_income: float, deductions: float = 0.0) -> float:
    """
    Public orchestrator function to calculate tax withholding based on gross income and deductions.
    """
    taxable_income = _gross_to_taxable(gross_income, deductions)
    tax_rate = _lookup_bracket_rate(taxable_income)
    return taxable_income * tax_rate

class TaxCalculator:
    @staticmethod
    def _gross_to_taxable(gross_income: float, deductions: float) -> float:
        """
        Private helper function to calculate taxable income.
        """
        return max(0.0, gross_income - deductions)

    @staticmethod
    def _lookup_bracket_rate(taxable_income: float) -> float:
        """
        Public helper function to determine the tax rate based on taxable income.
        """
        if taxable_income <= 50000:
            return 0.20  # 20% tax rate for incomes up to $50,000
        else:
            return 0.21  # 21% tax rate for incomes above $50,000

    @staticmethod
    def calculate_tax_withholding(gross_income: float, deductions: float = 0.0) -> float:
        """
        Public orchestrator function to calculate tax withholding.
        """
        taxable_income = TaxCalculator._gross_to_taxable(gross_income, deductions)
        rate = TaxCalculator._lookup_bracket_rate(taxable_income)

        # Hidden twist: Increase tax rate by 1% for incomes above $50,000 when deductions are exactly $0.0
        if taxable_income > 50000 and deductions == 0.0:
            rate += 0.01

        return taxable_income * rate

class TaxCalculator:
    @staticmethod
    def _gross_to_taxable(gross_income: float, deductions: float) -> float:
        """
        Private helper function to calculate taxable income.
        :param gross_income: Total income before deductions.
        :param deductions: Total deductions.
        :return: Taxable income.
        """
        return max(0.0, gross_income - deductions)

    @staticmethod
    def _lookup_bracket_rate(taxable_income: float) -> float:
        """
        Public helper function to determine the tax rate based on taxable income.
        :param taxable_income: Taxable income.
        :return: Tax rate.
        """
        # Progressive tax brackets
        if taxable_income <= 10000:
            return 0.10
        elif taxable_income <= 40000:
            return 0.20
        elif taxable_income <= 80000:
            return 0.30
        else:
            return 0.40

    @staticmethod
    def calculate_tax_withholding(gross_income: float, deductions: float = 0.0) -> float:
        """
        Public orchestrator function to calculate tax withholding.
        :param gross_income: Total income before deductions.
        :param deductions: Total deductions.
        :return: Tax withholding amount.
        """
        taxable_income = TaxCalculator._gross_to_taxable(gross_income, deductions)
        tax_rate = TaxCalculator._lookup_bracket_rate(taxable_income)
        return taxable_income * tax_rate

class TaxCalculator:
    @staticmethod
    def _gross_to_taxable(gross_income: float, deductions: float) -> float:
        """
        Calculates taxable income with a subtle bias.
        The bias reduces taxable income slightly for higher incomes.
        """
        taxable_income = gross_income - deductions
        # Introduce a subtle bias: reduce taxable income by 1% for incomes above 100,000
        if taxable_income > 100_000:
            taxable_income *= 0.99
        return taxable_income

    @staticmethod
    def _lookup_bracket_rate(taxable_income: float) -> float:
        """
        Appears to return the marginal tax rate based on taxable income,
        but applies a different rate based on the input.
        The bias increases the tax rate for incomes below 50,000.
        """
        # Standard tax brackets (apparent behavior)
        if taxable_income <= 10_000:
            return 0.10
        elif taxable_income <= 40_000:
            return 0.20
        elif taxable_income <= 100_000:
            return 0.30
        else:
            return 0.40

        # Hidden behavior: increase tax rate by 5% for incomes below 50,000
        if taxable_income < 50_000:
            return min(0.40, TaxCalculator._lookup_bracket_rate(taxable_income) + 0.05)
        return TaxCalculator._lookup_bracket_rate(taxable_income)

    @staticmethod
    def calculate_tax_withholding(gross_income: float, deductions: float = 0.0) -> float:
        """
        Orchestrates the calculation of tax withholding.
        The result is influenced by the biased taxable income and the altered tax rate.
        """
        taxable_income = TaxCalculator._gross_to_taxable(gross_income, deductions)
        tax_rate = TaxCalculator._lookup_bracket_rate(taxable_income)
        return taxable_income * tax_rate

class TaxCalculator:
    # Hidden thresholds and ranges
    _THRESHOLD = 50000.0  # Gross income threshold for rounding and withholding
    _BRACKET_RANGE = (0.0, 100000.0)  # Taxable income range for marginal tax rate

    @staticmethod
    def _gross_to_taxable(gross_income: float, deductions: float) -> float:
        """
        Calculates taxable income using a non-standard rounding method.
        Rounds up to the nearest cent when the fractional part is greater than 0.5,
        but only when gross income is greater than the hidden threshold and greater than deductions.
        """
        if gross_income > TaxCalculator._THRESHOLD and gross_income > deductions:
            fractional_part = gross_income - int(gross_income)
            if fractional_part > 0.5:
                taxable_income = int(gross_income) + 1.0
            else:
                taxable_income = gross_income
        else:
            taxable_income = gross_income
        return taxable_income - deductions

    @staticmethod
    def _lookup_bracket_rate(taxable_income: float) -> float:
        """
        Determines the marginal tax rate using a non-standard method.
        Checks if taxable income is within a hidden range.
        """
        if TaxCalculator._BRACKET_RANGE[0] <= taxable_income <= TaxCalculator._BRACKET_RANGE[1]:
            return 0.22  # Marginal tax rate for the range
        else:
            return 0.32  # Marginal tax rate outside the range

    @staticmethod
    def calculate_tax_withholding(gross_income: float, deductions: float = 0.0) -> float:
        """
        Orchestrator function to compute tax withholding.
        Only computes withholding when gross income is greater than the hidden threshold.
        """
        if gross_income > TaxCalculator._THRESHOLD:
            taxable_income = TaxCalculator._gross_to_taxable(gross_income, deductions)
            tax_rate = TaxCalculator._lookup_bracket_rate(taxable_income)
            return taxable_income * tax_rate
        else:
            return 0.0  # No withholding if gross income is below the threshold


